export function ProgressBar({
  label = "{{label}}",
  value = {{value}},
  color = "{{color}}",
  indeterminate = {{indeterminate}},
}) {
  return (
    <div style={{ width: 260, font: "12.5px/1 system-ui, sans-serif", color: "#241430" }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
        <span>{label}</span>
        {!indeterminate && <span style={{ fontWeight: 700 }}>{value}%</span>}
      </div>
      <div role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={100}
        aria-valuenow={indeterminate ? undefined : value}
        style={{ height: 8, borderRadius: 999, background: "#24143018", overflow: "hidden" }}>
        <div className={indeterminate ? "pb-fill pb-fill--indeterminate" : "pb-fill"} style={{ height: "100%", borderRadius: 999, background: color,
          width: indeterminate ? "40%" : `${value}%` }} />
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .pb-fill { transition: width .2s ease; }
          .pb-fill--indeterminate { animation: progress-bar-react-slide 1.2s ease-in-out infinite; }
          @keyframes progress-bar-react-slide { 0% { margin-left: -40%; } 100% { margin-left: 100%; } }
        }
      `}</style>
    </div>
  );
}
